def transform(g):
    h,w=len(g),len(g[0])
    # find 2x2 block of value 2
    top=left=None
    for r in range(h-1):
        for c in range(w-1):
            if g[r][c]==2 and g[r][c+1]==2 and g[r+1][c]==2 and g[r+1][c+1]==2:
                top,left=r,c
    out=[row[:] for row in g]
    # corner cell coords and ray directions
    corners={'TL':((top-1,left-1),(-1,-1)),'TR':((top-1,left+2),(-1,1)),
             'BL':((top+2,left-1),(1,-1)),'BR':((top+2,left+2),(1,1))}
    color={k:g[rc[0]][rc[1]] for k,rc in corners.items()}
    # ray color = color of corner one step counterclockwise: TL<-BL, BL<-BR, BR<-TR, TR<-TL
    src={'TL':'BL','TR':'TL','BR':'TR','BL':'BR'}
    for k,(rc,d) in corners.items():
        r,c=rc
        while 0<=r<h and 0<=c<w:
            out[r][c]=color[src[k]]
            r+=d[0]; c+=d[1]
    return out
