def corners_of(g,top,left):
    return {'TL':(top-1,left-1),'TR':(top-1,left+2),'BL':(top+2,left-1),'BR':(top+2,left+2)}

def transform_multi(g, stop_fn=None):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    blocks=find_blocks(g)
    info=[]
    for top,left in blocks:
        pos=corners_of(g,top,left)
        colors={k:g[r][c] for k,(r,c) in pos.items()}
        info.append((top,left,pos,colors))
    for top,left,pos,colors in info:
        for k in 'TL TR BL BR'.split():
            r0,c0=pos[k]; dr,dc=DIRS[k]; col=colors[SRC[k]]
            r,c=r0,c0
            while 0<=r<h and 0<=c<w:
                if stop_fn and stop_fn(r,c,top,left,col,info,out): break
                out[r][c]=col
                r+=dr; c+=dc
    return out

